/// Gather D0..D7 out of a raw SIO input word.
#[inline(always)]
pub fn gather_data(raw: u32) -> u8 {
    let mut v = 0u8;
    let mut i = 0;
    while i < 8 {
        v |= (((raw >> DATA_GPIO[i]) & 1) as u8) << i;
        i += 1;
    }
    v
}
